import { entry as e } from "./entry.js";

export default [
  e("react-components", "Components", "react components|react component", "A React component describes part of a UI from its inputs. Function components return renderable values.\nKeep rendering pure; event handlers handle user actions and effects synchronize with external systems."),
  e("react-jsx", "JSX", "jsx", "JSX is syntax transformed into JavaScript element creation calls.\nUse braces for expressions, className for CSS classes, and capitalized names for components.\nReact escapes text values; never insert untrusted raw HTML."),
  e("react-props-state", "Props versus state", "props vs state|props and state", "Props are inputs passed by a parent; state is component-owned memory across renders.\nTreat both as immutable snapshots. Ask the owner to update a prop rather than mutating it."),
  e("react-usestate", "useState", "usestate", "useState supplies a state snapshot and a setter that schedules a render.\nWhen the next value depends on the previous value, use a functional update like setCount(c => c + 1).\nSetting state does not change the variable in the currently running handler."),
  e("react-useeffect", "useEffect and cleanup", "useeffect cleanup|useeffect|effect cleanup", "useEffect synchronizes with an external system after a commit.\nInclude every reactive dependency used by the effect. Cleanup runs before changed-dependency setup and on unmount.\nPair subscriptions with unsubscription and guard or cancel stale async work."),
  e("react-useref", "useRef", "useref", "useRef holds a mutable value whose identity persists across renders.\nChanging ref.current does not trigger a render. Use refs for DOM nodes, timers, or non-rendered values.\nUse state for information that should update the visible UI."),
  e("react-usememo", "useMemo", "usememo", "useMemo caches a calculation result while its dependencies remain equal by Object.is.\nIt is a performance optimization, not a correctness guarantee.\nKeep the calculation pure and measure whether caching actually helps."),
  e("react-usecallback", "useCallback", "usecallback", "useCallback caches a function identity between renders while dependencies stay equal.\nUseful when identity matters to a memoized child or subscription.\nIt does not stop the component itself from rendering or make the function faster."),
  e("react-usecontext", "useContext", "usecontext", "useContext reads the nearest matching provider's value above the component.\nConsumers re-render when that value changes by Object.is.\nAvoid creating unnecessary new provider objects when many consumers depend on them."),
  e("react-usereducer", "useReducer", "usereducer", "useReducer organizes state transitions as a pure reducer(state, action).\nDispatch describes what happened; the reducer returns the next state without mutation.\nUseful when related transitions are easier to understand together."),
  e("react-custom-hooks", "Custom hooks", "custom hooks|custom hook", "A custom hook shares stateful logic and starts with use.\nSeparate callers get independent hook state unless they deliberately share an external store or context.\nFollow the same hook ordering rules inside custom hooks."),
  e("react-keys", "List keys", "react keys|list keys", "Keys identify siblings across renders so React can preserve the right state and DOM.\nUse stable data IDs rather than random values or changing array positions.\nkey is not passed as a normal prop; pass an ID separately if needed."),
  e("react-controlled", "Controlled inputs", "controlled inputs|controlled input", "A controlled input receives its value or checked state from React and updates it in onChange.\nKeep text values consistently strings to avoid controlled/uncontrolled switches.\nIt gives one explicit source of truth for validation and submission."),
  e("react-uncontrolled", "Uncontrolled inputs", "uncontrolled inputs|uncontrolled input", "An uncontrolled input keeps its current value in the DOM.\nUse defaultValue for its initial value and a ref or FormData when reading it.\nUpdating defaultValue is not the same as controlling the current value."),
  e("react-reconciliation", "Reconciliation", "reconciliation|virtual dom", "React compares rendered element descriptions to decide what to update.\nElement type, position, and keys influence whether component state is preserved or reset.\nThe virtual DOM is a description, not a guarantee that every React update is cheaper than hand-written DOM work."),
  e("react-lifting-state", "Lifting state up", "lifting state up", "Move shared state to the closest common owner of components that need it.\nPass values down and callbacks for requesting changes.\nThis avoids conflicting copies of the same information."),
  e("react-router", "React Router", "react router", "A client router maps URLs to UI and supports navigation without a full page load.\nUse router links for in-app navigation. The server still needs an SPA fallback for direct route refreshes.\nClient route guards do not replace server authorization."),
  e("react-context-redux", "Context versus Redux", "context vs redux|context versus redux", "Context distributes a value; it does not prescribe how state updates are organized.\nRedux adds a store, explicit update flow, selectors, and tooling.\nChoose based on state complexity and update patterns, not the assumption that every app needs a global store."),
  e("react-memo", "React.memo", "react memo|react.memo|component memoization", "memo can skip a component render when its props compare equal.\nState updates and consumed context changes can still render it.\nNew object/function props can defeat shallow comparison; profile before adding memoization."),
  e("react-strictmode", "StrictMode", "strictmode|strict mode double invoke", "StrictMode performs extra development checks, including extra render calls and effect setup/cleanup cycles.\nThey expose impure rendering and missing cleanup.\nDo not suppress them with a global already-ran flag; make setup and cleanup safe."),
  e("react-lazy", "Code splitting", "react lazy|code splitting|suspense", "lazy defers loading a component module until it is rendered; show a Suspense fallback while loading.\nThe module normally supplies a default component export.\nDeclare lazy components outside other components and handle loading failures with an error boundary."),
  e("react-hook-rules", "Rules of hooks", "rules of hooks|hook rules", "Call hooks at the top level of components or custom hooks, not in loops, conditions, or ordinary callbacks.\nKeep the call order stable across renders and include correct dependencies.\nReact's special use API has distinct rules; ordinary hooks still follow top-level ordering."),
  e("react-error-boundary", "Error boundaries", "error boundaries|error boundary", "An error boundary displays fallback UI when a descendant throws during rendering.\nIt does not generally catch errors in event handlers or unrelated async callbacks.\nHandle those failures in their own paths and provide a useful recovery action."),
  e("react-immutable-state", "Immutable state updates", "immutable state updates|react immutability", "Create a new object or array when updating state rather than changing the existing snapshot.\nCopy every nested level that changes; a top-level spread alone still shares nested objects.\nThis makes updates predictable and supports identity comparisons."),
  e("react-derived-state", "Derived state", "derived state", "If a value can be calculated from existing props/state during rendering, calculate it there.\nDuplicating it in state can create synchronization bugs and extra renders.\nUse memoization only if the calculation is expensive enough to justify it."),
].map(item => ({ ...item, topic: "react" }));
